import{_ as l,l as n,o as e,c as o,v as r,p as i,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"BSGS 离散对数","description":"","frontmatter":{"title":"BSGS 离散对数","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bsgs.md","filePath":"cs/bsgs.md","lastUpdated":1789023840000}'),c={name:"cs/bsgs.md"};function m(g,a,S,_,u,B){const s=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="bsgs-离散对数" tabindex="-1">BSGS 离散对数 <a class="header-anchor" href="#bsgs-离散对数" aria-label="Permalink to &quot;BSGS 离散对数&quot;">​</a></h1><div class="epigraph"><p>$g^x=a$ 在阶 $n$ 的群里，拆 $x=i\\lfloor\\sqrt n\\rfloor-j$，建小步表再大步查：$O(\\sqrt n)$ 时间与空间。</p><footer>—— 据 Shanks, Class Number, a Theory of Factorization and Genera, 1971；[离散对数](/cs/generator-discrete-log) 对照整理</footer></div><p>上一课<a href="/cs/euler-mobius">欧拉函数与莫比乌斯</a>给了模 \\(p\\) 的阶相关函数。主干已定义离散对数。缺口是<strong>算法</strong>：Baby-step giant-step（BSGS）。不重写原根存在性。后课 Pollard rho 也可离散对数，本课先确定性根号。接<a href="/cs/fast-exponentiation">快速幂</a>算 \\(g^k\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>循环群 \\(\\langle g\\rangle\\) 阶 \\(n\\)，\\(a\\in\\langle g\\rangle\\)，求 \\(x\\)。令 \\(m=\\lceil\\sqrt n\\rceil\\)，\\(x=im-j\\)，\\(0\\le j\\lt m\\)。则 \\(g^{im}=a g^{j}\\)。枚举 \\(j\\) 存 \\(a g^j\\)（或 \\(g^j\\)）入哈希；枚举 \\(i\\) 算 \\(g^{im}\\) 查询。时间空间 \\(O(\\sqrt n)\\)。</p><p>缺口是时间–空间折中，不是 NP 证书。Pohlig–Hellman 先把 \\(n\\) 分解成小素因子再 CRT，点名。</p><h3 id="不是线性筛那种" tabindex="-1">不是线性筛那种 \\(O(n)\\) <a class="header-anchor" href="#不是线性筛那种" aria-label="Permalink to &quot;不是线性筛那种 $O(n)$&quot;">​</a></h3><p>\\(n\\) 是群阶，可 \\(2^{256}\\)，根号仍不可行。本课算法在 \\(n\\approx 10^{12}\\) 量级可谈。密码学离散对数要亚指数（NFS），不在本课。</p><p><span class="marginnote">Shanks BSGS。Pollard rho 离散对数均摊同阶、空间更小。后课 rho 主讲分解，对数变体点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>确定 \\(n\\)（或倍数）。建小步哈希。大步乘 \\(g^m\\)。注意 \\(j\\) 的符号约定与空解。</p>',11)),(e(),i(p,null,{default:t(()=>[h(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22x%20%3D%20i%20m%20-%20j%22%5D%20--%3E%20BABY%5B%22%E5%B0%8F%E6%AD%A5%EF%BC%9A%E5%93%88%E5%B8%8C%20a%20g%5Ej%22%5D%0A%20%20X%20--%3E%20GIANT%5B%22%E5%A4%A7%E6%AD%A5%EF%BC%9Ag%5E%7Bi%20m%7D%20%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20BABY%20--%3E%20HIT%5B%22%E5%91%BD%E4%B8%AD%E5%88%99%20x%22%5D%0A%20%20GIANT%20--%3E%20HIT%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>群运算须能哈希元素。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>任何 \\(x\\in[0,n)\\) 必有一种 \\(i,j\\) 拆法。哈希期望 \\(O(1)\\)。与穷举 \\(O(n)\\) 比根号。与 BSGS 矩阵离散对数（Baby-step 在 GL）点名不同群。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 index calculus。不写椭圆曲线专用（仍可用 BSGS，阶不同）。后课默认：小阶离散对数 BSGS \\(O(\\sqrt n)\\)。下一课 Pollard rho 分解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大步小步 \\(O(\\sqrt n)\\) 时间空间。</li><li>须知阶（或上界）。</li><li>大阶密码实例不靠本课。</li><li>出处：Shanks, 1971。</li></ul>',7))])}const b=l(c,[["render",m]]);export{f as __pageData,b as default};
